void kernel_jacobi_1d_imper(int tsteps, int n, DATA_TYPE POLYBENCH_1D(A, N, n),
                             DATA_TYPE POLYBENCH_1D(B, N, n)) {
    int t, i, j;
    DATA_TYPE temp;

    // Initialize boundary conditions
    for (int k = 0; k < n; k++) {
        A[k] = k + 1;
        B[k] = 0.0f;
    }

    // Main loop for time-stepping
    #pragma omp parallel for schedule(static)
    for (t = 0; t < tsteps; t++) {
        #pragma omp barrier

        // Calculate new values in A
        for (i = 0; i < n; i++) {
            for (j = i; j < n; j++) {
                temp = 0.0f;
                for (int k = 0; k < n; k++) {
                    temp += (A[i][k] - A[i][N]) * (A[j][k] - A[j][N]);
                }
                B[i][j] = temp / (A[i][N+1] * A[j][N+1] * (N - 1));
                B[j][i] = B[i][j];
            }
        }

        // Barrier after each time step
        #pragma omp barrier

        // Update A
        for (i = 0; i < n; i++) {
            for (j = i; j < n; j++) {
                A[j] = B[j];
            }
        }
    }
}

